use xiom.io;

fn safe_sqrt(n: Int) -> Option[Int] {
  if n < 0 { return None; }
  let i = 0;
  while i * i <= n {
    if i * i == n { return Some(i); }
    i = i + 1;
  }
  return None;
}

fn safe_divide(a: Int, b: Int) -> Option[Int] {
  if b == 0 { return None; }
  return Some(a / b);
}

fn safe_power(base: Int, exp: Int) -> Option[Int] {
  if exp < 0 { return None; }
  let result = 1;
  let i = 0;
  while i < exp {
    result = result * base;
    i = i + 1;
  }
  return Some(result);
}

fn main() -> Int {
  io.println(safe_sqrt(16).unwrap_or(-1).to_str());
  io.println(safe_sqrt(-9).unwrap_or(-1).to_str());
  io.println(safe_divide(20, 4).unwrap_or(-1).to_str());
  io.println(safe_divide(20, 0).unwrap_or(-1).to_str());
  io.println(safe_power(2, 3).unwrap_or(-1).to_str());
  io.println(safe_power(2, -1).unwrap_or(-1).to_str());
  return 0;
}
